async function getProduct(id) {
  const key = `product:${id}`;
  const hit = await cache.get(key);
  if (hit) return JSON.parse(hit);
  const row = await db.findProduct(id);
  await cache.set(key, JSON.stringify(row), { EX: 300 }); // TTL 5 นาที
  return row;
}

